import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class GoodExample {
    public static void main(String[] args) throws IOException, InterruptedException {
        // Read a user input string from the console
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.print("Enter command (only 'ls' or 'date' allowed): ");
        String userInput = reader.readLine();

        // Validate the input strictly against a whitelist of allowed commands.
        // This prevents attackers from injecting shell metacharacters like ';' or '|'.
        if ("ls".equals(userInput) || "date".equals(userInput)) {
            // Construct the argument list safely. Pass arguments as separate strings
            // to avoid shell interpretation issues entirely.
            String[] commandArgs = new String[]{"/bin/sh", "-c", userInput};

            // Execute the command with a safe process builder approach.
            ProcessBuilder pb = new ProcessBuilder(commandArgs);
            Process process = pb.start();

            // Wait for the process to complete and handle output/error streams.
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } else {
            System.out.println("Invalid command. Access denied.");
        }
    }
}
